 private void styleButton(Button b,int bg,int fg){b.setAllCaps(false);b.setTextSize(14);b.setTextColor(fg);b.setTypeface(android.graphics.Typeface.create("sans-serif-medium",android.graphics.Typeface.NORMAL));b.setMinHeight(dp(48));b.setPadding(dp(14),dp(8),dp(14),dp(8));android.graphics.drawable.GradientDrawable d=new android.graphics.drawable.GradientDrawable();d.setColor(bg);d.setCornerRadius(dp(7));b.setBackground(d);if(android.os.Build.VERSION.SDK_INT>=21)b.setStateListAnimator(null);}

 private void check(){check.setEnabled(false);status.setText("Checking update manifest…");io.execute(()->{try{HttpURLConnection c=(HttpURLConnection)new URL(MANIFEST_URL).openConnection();c.setConnectTimeout(15000);c.setReadTimeout(15000);c.setRequestProperty("Accept","application/json");if(c.getResponseCode()!=200)throw new Exception("Manifest HTTP "+c.getResponseCode());ByteArrayOutputStream b=new ByteArrayOutputStream();try(InputStream in=c.getInputStream()){byte[] x=new byte[8192];int n;while((n=in.read(x))!=-1)b.write(x,0,n);}c.disconnect();JSONObject m=new JSONObject(new String(b.toByteArray(),java.nio.charset.StandardCharsets.UTF_8));if(!"lavender".equals(m.optString("device")))throw new Exception("Manifest device mismatch");String url=m.getString("url"),sha=m.getString("sha256");if(!url.startsWith("https://"))throw new Exception("Refusing non-HTTPS URL");if(!sha.matches("(?i)[0-9a-f]{64}")||sha.matches("0{64}"))throw new Exception("Invalid or placeholder checksum");release=m;runOnUiThread(()->{status.setText("Update "+m.optString("version","unknown")+" available.\n"+m.optString("changelog",""));check.setEnabled(true);download.setEnabled(true);});}catch(Exception e){runOnUiThread(()->{status.setText("Update check failed: "+e.getMessage());check.setEnabled(true);download.setEnabled(false);});}});}
 private void download(){if(release==null){status.setText("Check for updates first; no release manifest is loaded.");return;}downloadStartedAt=System.currentTimeMillis();downloadTimeoutReported=false;trackingDownload=true;getSharedPreferences("updater",0).edit().putString("download_status","Starting protected download…").putInt("download_status_progress",-1).putBoolean("download_status_determinate",false).putBoolean("download_status_done",false).putLong("download_status_time",downloadStartedAt).apply();download.setEnabled(false);install.setEnabled(false);progress.setIndeterminate(true);status.setText("Starting protected download…");Intent i=new Intent(this,DownloadService.class);i.putExtra(DownloadService.URL,release.optString("url"));i.putExtra(DownloadService.SHA,release.optString("sha256"));i.putExtra(DownloadService.VERSION,release.optString("version"));try{if(android.os.Build.VERSION.SDK_INT>=26)startForegroundService(i);else startService(i);downloadHandler.removeCallbacks(downloadPoll);downloadHandler.postDelayed(downloadPoll,250);downloadHandler.postDelayed(()->{if(!isFinishing()&&trackingDownload&&!downloadTimeoutReported){syncDownloadState();if(trackingDownload&&status.getText().toString().startsWith("Starting protected download")){downloadTimeoutReported=true;status.setText("No status was recorded from the download service after 12 seconds. This points to a service-start/reporting problem; internet access has not yet been tested. Keep the app open briefly. If this repeats, send this exact message and the phone’s Android version/build.");progress.setIndeterminate(false);download.setEnabled(true);}}},12000);}catch(Exception e){trackingDownload=false;downloadHandler.removeCallbacks(downloadPoll);download.setEnabled(true);progress.setIndeterminate(false);status.setText("Could not start download service ("+e.getClass().getSimpleName()+"): "+e.getMessage());}}private void syncDownloadState(){if(!trackingDownload)return;android.content.SharedPreferences p=getSharedPreferences("updater",0);long eventTime=p.getLong("download_status_time",0);String msg=p.getString("download_status",null);if(msg==null||eventTime<downloadStartedAt||(eventTime==downloadStartedAt&&msg.startsWith("Starting protected download")))return;status.setText(msg);boolean det=p.getBoolean("download_status_determinate",false);boolean done=p.getBoolean("download_status_done",false);int pct=p.getInt("download_status_progress",-1);progress.setIndeterminate(!det&&!done&&!msg.startsWith("Download failed"));if(det)progress.setProgress(Math.max(0,Math.min(100,pct)));if(done){verifiedZip=new File(getFilesDir(),"lucidos-update.zip");install.setEnabled(verifiedZip.isFile());download.setEnabled(true);trackingDownload=false;downloadHandler.removeCallbacks(downloadPoll);}else if(msg.startsWith("Download failed")){install.setEnabled(false);download.setEnabled(true);trackingDownload=false;downloadHandler.removeCallbacks(downloadPoll);}else{install.setEnabled(false);download.setEnabled(false);}}
 private void confirmInstall(){new AlertDialog.Builder(this).setTitle("Install LucidOS update?").setMessage("The verified ZIP will be copied to Download, a recovery install script will be staged using root, and the phone will reboot into recovery. This overwrites system partitions and can leave the phone unbootable if the package/recovery is incompatible. Back up important data first. Continue?").setNegativeButton("Cancel",null).setPositiveButton("Reboot & install",(d,w)->stageAndReboot()).show();}
 private void stageAndReboot(){verifiedZip=new File(getFilesDir(),"lucidos-update.zip");if(verifiedZip==null||!verifiedZip.isFile()||!getSharedPreferences("updater",0).getBoolean("download_verified",false)){status.setText("No verified update file. Download it first.");return;}install.setEnabled(false);download.setEnabled(false);check.setEnabled(false);status.setText("Staging recovery install with root…");io.execute(()->{try{if(!sha256(verifiedZip).equalsIgnoreCase(release.getString("sha256")))throw new Exception("Verified file changed; download again");String path=verifiedZip.getAbsolutePath().replace("'","'\\''");String dest=RECOVERY_ZIP.replace("'","'\\''");String script="set -e; mkdir -p /sdcard/Download /cache/recovery; cp '"+path+"' '"+dest+"'; chmod 0644 '"+dest+"'; sync; printf '%s\\n' 'install "+RECOVERY_ZIP+"' 'reboot' > /cache/recovery/openrecoveryscript; chmod 0644 /cache/recovery/openrecoveryscript; sync";runRoot(script);runOnUiThread(()->status.setText("Recovery script staged. Rebooting into recovery…"));runRoot("reboot recovery");runOnUiThread(()->{status.setText("Reboot command returned. If the phone did not reboot, check root permission and recovery compatibility.");check.setEnabled(true);download.setEnabled(true);});}catch(Exception e){runOnUiThread(()->{status.setText("Could not stage update: "+e.getMessage());install.setEnabled(true);download.setEnabled(true);check.setEnabled(true);});}});}
 private void runRoot(String command)throws Exception{Process p=new ProcessBuilder("su","-c",command).redirectErrorStream(true).start();ByteArrayOutputStream b=new ByteArrayOutputStream();try(InputStream in=p.getInputStream()){byte[] x=new byte[4096];int n;while((n=in.read(x))!=-1){if(b.size()<32768)b.write(x,0,n);}}if(!p.waitFor(30,java.util.concurrent.TimeUnit.SECONDS)){p.destroyForcibly();throw new Exception("Root command timed out");}int code=p.exitValue();if(code!=0)throw new Exception("su exit "+code+": "+b.toString("UTF-8"));}
 private String sha256(File f)throws Exception{MessageDigest d=MessageDigest.getInstance("SHA-256");try(InputStream in=new FileInputStream(f)){byte[] b=new byte[131072];int n;while((n=in.read(b))!=-1)d.update(b,0,n);}StringBuilder s=new StringBuilder();for(byte b:d.digest())s.append(String.format(Locale.ROOT,"%02x",b&255));return s.toString();}
  @Override protected void onResume(){super.onResume();if(downloadReceiver!=null){IntentFilter f=new IntentFilter(DownloadService.ACTION);if(android.os.Build.VERSION.SDK_INT>=33)registerReceiver(downloadReceiver,f,Context.RECEIVER_NOT_EXPORTED);else registerReceiver(downloadReceiver,f);}} @Override protected void onPause(){if(downloadReceiver!=null){try{unregisterReceiver(downloadReceiver);}catch(Exception ignored){}}super.onPause();} private TextView text(String s,int z,int c,boolean bold){TextView t=new TextView(this);t.setText(s);t.setTextSize(z);t.setTextColor(c);if(bold)t.setTypeface(null,1);return t;}private void add(LinearLayout p,View v,int top){LinearLayout.LayoutParams l=new LinearLayout.LayoutParams(-1,-2);l.topMargin=top;p.addView(v,l);}private int dp(float x){return (int)(x*getResources().getDisplayMetrics().density+0.5f);}@Override protected void onDestroy(){trackingDownload=false;downloadHandler.removeCallbacks(downloadPoll);io.shutdownNow();super.onDestroy();}
